// Group completed issues by project and build the Slack and Notion versions of the digest.
const cfg = $('Config').first().json;
const issues = $input.first().json.data?.issues?.nodes ?? [];

const byProject = {};
for (const i of issues) {
  const p = i.project?.name ?? 'No project';
  (byProject[p] ??= []).push(i);
}
const projects = Object.keys(byProject).sort((a, b) => byProject[b].length - byProject[a].length);

const weekEnding = $now.setZone(cfg.timezone).toFormat('d LLL yyyy');
const title = `Shipped this week (${cfg.team_key}), week ending ${weekEnding}`;

let slack = `*${title}*\n`;
const blocks = [
  { object: 'block', type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: title } }] } },
];

if (issues.length === 0) {
  slack += 'Nothing moved to Done in the last 7 days.';
  blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [{ type: 'text', text: { content: 'Nothing moved to Done in the last 7 days.' } }] } });
} else {
  slack += `${issues.length} issue${issues.length === 1 ? '' : 's'} across ${projects.length} project${projects.length === 1 ? '' : 's'}\n`;
  for (const p of projects) {
    slack += `\n*${p}*\n`;
    blocks.push({ object: 'block', type: 'heading_3', heading_3: { rich_text: [{ type: 'text', text: { content: p } }] } });
    for (const i of byProject[p]) {
      const who = i.assignee?.name ? ` (${i.assignee.name})` : '';
      slack += `• <${i.url}|${i.identifier}> ${i.title}${who}\n`;
      blocks.push({
        object: 'block', type: 'bulleted_list_item',
        bulleted_list_item: { rich_text: [
          { type: 'text', text: { content: i.identifier, link: { url: i.url } } },
          { type: 'text', text: { content: ` ${i.title}${who}` } },
        ] },
      });
    }
  }
}
blocks.push({ object: 'block', type: 'divider', divider: {} });

return [{ json: { title, count: issues.length, projects: projects.length, slack_text: slack, notion_children: blocks } }];
